package com.example.editor.textual.persistence;
import java.util.*;import org.springframework.stereotype.Repository;import com.example.editor.textual.*;import com.example.editor.textual.runtime.TextualModelSession;import com.example.editor.persistence.*;import com.example.editor.validation.persistence.StoredCanonicalDocument;import tools.jackson.databind.ObjectMapper;
@Repository public class JsonTextualModelSessionRepository implements TextualModelSessionRepository{private final CanonicalDocumentStore<TextualModelSession>store;/** Descripción: Inicializa una instancia de JsonTextualModelSessionRepository con sus dependencias y datos de entrada. Entradas: p: dato de entrada necesario para la operación; m: dato de entrada necesario para la operación; f: dato de entrada necesario para la operación. Salida: deja la instancia inicializada y lista para su uso. */ public JsonTextualModelSessionRepository(TextualModelProperties p,ObjectMapper m,CanonicalDocumentStoreFactory f){store=f.create(new CanonicalDocumentStoreSpec<>("textual.model.session",p.getSessionDirectory(),p.getSessionFileSuffix(),p.isUseEtag(),m,TextualModelSession.class,TextualModelSession::id));}/** Descripción: Crea o prepara el resultado de «create» dentro de JsonTextualModelSessionRepository. Entradas: s: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public StoredCanonicalDocument<TextualModelSession>create(TextualModelSession s){return store.create(s);}/** Descripción: Actualiza el estado gestionado por JsonTextualModelSessionRepository mediante la operación «replace». Entradas: id: identificador que delimita el recurso objetivo; s: dato de entrada necesario para la operación; e: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public StoredCanonicalDocument<TextualModelSession>replace(String id,TextualModelSession s,String e){return store.replace(id,s,e);}/** Descripción: Obtiene la información correspondiente a «find» dentro de JsonTextualModelSessionRepository. Entradas: id: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ public Optional<StoredCanonicalDocument<TextualModelSession>>find(String id){return store.find(id);}/** Descripción: Obtiene la información correspondiente a «listIds» dentro de JsonTextualModelSessionRepository. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public List<String>listIds(){return store.listIds();}}
